using ProjectTower.config;

namespace ProjectTower.sanctuary;

public class Creeds
{
	public struct CreedDef(int ID, string altMonsterStr, string consumableHP, string consumableMP, string consumableSlot1, string consumableSlot2)
	{
		public int ID = ID;

		public string altMonsterStr = altMonsterStr;

		public string[] consumable = new string[4] { consumableHP, consumableMP, consumableSlot1, consumableSlot2 };

		public const int CONSUMABLE_HP = 0;

		public const int CONSUMABLE_MP = 1;

		public const int CONSUMABLE_SLOT_1 = 2;

		public const int CONSUMABLE_SLOT_2 = 3;
	}

	public const int CREED_NONE = 0;

	public const int CREED_IRON = 1;

	public const int CREED_CLERIC = 2;

	public const int CREED_THREE = 3;

	public const int CREED_WOODS = 4;

	public const int CREED_DARK = 5;

	public const int CREED_SPLENDOR = 6;

	public const int CREED_UNUSED_1 = 7;

	public const int CREED_FIRE = 8;

	public const int CREED_UNUSED_2 = 9;

	public const int CREED_CANDLE = 10;

	public const int TOTAL_CREEDS = 10;

	public const int CREED_LEVEL_APOSTATE = -1;

	public const int CREED_LEVEL_UNAFFILIATED = 0;

	public const int CREED_LEVEL_BUFF = 1;

	public const int TOTAL_UNLOCKS = 4;

	public static CreedDef[] creedDef;

	public static void Init()
	{
		creedDef = new CreedDef[10];
		creedDef[1] = new CreedDef(1, "_iron", "roll", "mana_crystal", "buff_sanclit", "horn_sanc_will");
		creedDef[2] = new CreedDef(2, "_cleric", "water", "mana_cloth", "potion_holy", "buff_sancholy");
		creedDef[3] = new CreedDef(3, "_three", "potion", "mana_mead", "buff_sancfire", "buff_threelit");
		creedDef[4] = new CreedDef(4, "_woods", "heal_herb", "mana_herb", "buff_sancpoison", "throw_w_dagger/25");
		creedDef[8] = new CreedDef(8, "_fire", "fire_flask", "blue_sky", "buff_crystal", "buff_sancfocus");
		creedDef[5] = new CreedDef(5, "_dark", "blood_vial", "black_salt", "buff_sancdark", "blood_pot/3");
		creedDef[6] = new CreedDef(6, "_splendor", "red_wine", "blue_wine", "gold_wine", (GameModeMgr.currentMode == 1) ? "cleansing_cloth" : "cleansing_cloth/2");
		creedDef[7] = new CreedDef(7, "_fool", "potion", "mana_mead", "buff_sancfire", "buff_threelit");
		creedDef[9] = new CreedDef(9, "_bones", "potion", "mana_mead", "buff_sancfire", "buff_threelit");
	}
}
using MapEdit;
using MapEdit.map;
using Microsoft.Xna.Framework;
using ProjectTower.character;
using ProjectTower.gamestate;
using ProjectTower.map;
using ProjectTower.player;
using ProjectTower.texturesheet;

namespace ProjectTower.sanctuary;

public class SanctuaryMgr
{
	public Sanctuary[] sanctuaries;

	public const int SANCTUARY_ASHEN_SHORE = 0;

	public const int SANCTUARY_FORSAKEN_VILLAGE = 1;

	public const int SANCTUARY_BANDITS_PASS = 2;

	public const int SANCTUARY_CASTLE_OF_STORMS = 3;

	public const int SANCTUARY_SUNKEN_KEEP = 4;

	public const int SANCTUARY_RED_DUNGEON = 5;

	public const int SANCTUARY_LOST_WOODS = 6;

	public const int SANCTUARY_CAVES = 7;

	public const int SANCTUARY_SWAMP = 8;

	public const int SANCTUARY_DOME = 9;

	public const int SANCTUARY_SKY_CASTLE = 10;

	public const int SANCTUARY_DUNGEON_CAVE = 11;

	public const int SANCTUARY_FAR_BEACH = 12;

	public const int SANCTUARY_COASTAL_FORT = 13;

	public const int SANCTUARY_SIAM_LAKE = 14;

	public const int SANCTUARY_DARKWOOD = 15;

	public const int SANCTUARY_ZIGGURAT = 16;

	public const int SANCTUARY_RUINS = 17;

	public const int SHRINE_PARTY_FORT = 18;

	public const int SHRINE_SUNKEN_KEEP = 19;

	public const int SHRINE_RED_DUNGEON = 20;

	public const int SHRINE_DOME = 21;

	public const int SANCTUARY_LAB = 22;

	public const int SHRINE_SWAMP = 23;

	public const int SHRINE_CASTLE_OF_STORMS = 24;

	public const int SHRINE_CAVES = 25;

	public const int SANCTUARY_TOMB = 26;

	public const int SHRINE_TOMB = 27;

	public const int SHRINE_PALACE = 28;

	public const int SHRINE_DARKWOODS = 29;

	public const int SHRINE_UNKNOWN = 30;

	public const int SANCTUARY_BLACKEST_VAULT = 31;

	public const int MAX_SANCTUARIES = 40;

	public const int SANCTUARY_OTHER_CREED = 1000;

	public SanctuaryMgr()
	{
		sanctuaries = new Sanctuary[40];
	}

	public void Update(float frameTime)
	{
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			if (sanctuaries[i] != null)
			{
				sanctuaries[i].Update(frameTime);
			}
		}
	}

	public void Draw(float alpha)
	{
		float num = 1200f;
		float num2 = 600f;
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			if (sanctuaries[i] != null && sanctuaries[i].loc.X > ScrollManager.scroll.X - num && sanctuaries[i].loc.X < ScrollManager.scroll.X + num && sanctuaries[i].loc.Y > ScrollManager.scroll.Y - num2 && sanctuaries[i].loc.Y < ScrollManager.scroll.Y + num2)
			{
				sanctuaries[i].Draw(alpha);
				sanctuaries[i].DrawBack(alpha);
			}
		}
	}

	public void InitFromMap()
	{
		int num = 0;
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			sanctuaries[i] = null;
		}
		for (int j = 0; j < 2; j++)
		{
			Layer layer = MapMgr.map.layer[(j == 0) ? 15 : 5];
			for (int k = 0; k < layer.seg.Length; k++)
			{
				Seg seg = layer.seg[k];
				if (seg != null && Textures.tex[seg.textureIdx].GetOriginalCell(seg.idx).flags == 11 && num < sanctuaries.Length)
				{
					sanctuaries[num] = new Sanctuary(seg, num);
					num++;
				}
			}
		}
	}

	internal int GetSanctuaryIn(Character c)
	{
		int num = (int)(c.loc.X / 64f);
		int num2 = (int)(c.loc.Y / 32f);
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			if (sanctuaries[i] != null && num >= sanctuaries[i].left && num <= sanctuaries[i].right && num2 >= sanctuaries[i].top && num2 <= sanctuaries[i].bottom + 1)
			{
				return i;
			}
		}
		return -1;
	}

	internal int GetSanctuaryClaim(Player p, int sanctIn)
	{
		Character playerCharacter = CharMgr.GetPlayerCharacter(p);
		if (playerCharacter == null)
		{
			return -1;
		}
		if (p.ID == GameStateManager.coopPlayerIdx)
		{
			return -1;
		}
		float num = 120f;
		if (sanctuaries[sanctIn] != null)
		{
			if (sanctuaries[sanctIn].creed == 0)
			{
				Vector2 loc = sanctuaries[sanctIn].loc;
				if (playerCharacter.loc.Y <= loc.Y + 128f && playerCharacter.loc.Y > loc.Y && playerCharacter.loc.X < loc.X + num && playerCharacter.loc.X > loc.X - num)
				{
					return sanctIn;
				}
			}
			else
			{
				Vector2 loc2 = sanctuaries[sanctIn].loc;
				if (playerCharacter.loc.Y <= loc2.Y + 128f && playerCharacter.loc.Y > loc2.Y && playerCharacter.loc.X < loc2.X + num && playerCharacter.loc.X > loc2.X - num)
				{
					return sanctIn + 1000;
				}
			}
		}
		return -1;
	}

	internal int GetSanctuaryBuy(Player p, int sanctIn)
	{
		Character playerCharacter = CharMgr.GetPlayerCharacter(p);
		if (playerCharacter == null)
		{
			return -1;
		}
		float num = 120f;
		Sanctuary sanctuary = sanctuaries[sanctIn];
		if (sanctuary != null && sanctuary.creed != 0 && sanctuary.desecrationFrame <= 0f && p.creedStanding[sanctuary.creed] >= 0)
		{
			Vector2 loc = sanctuary.loc;
			if (playerCharacter.loc.Y <= loc.Y + 128f && playerCharacter.loc.Y > loc.Y && ((playerCharacter.loc.X < loc.X + num / 2f && playerCharacter.loc.X > loc.X - num && playerCharacter.face == 1) || (playerCharacter.loc.X > loc.X - num / 2f && playerCharacter.loc.X < loc.X + num && playerCharacter.face == 0)))
			{
				return 8;
			}
			for (int i = 0; i < 4; i++)
			{
				int charIdx = sanctuary.sanctuaryChar[i].charIdx;
				if (charIdx > -1 && charIdx < 9999)
				{
					Character character = CharMgr.character[charIdx];
					if (playerCharacter.loc.Y < character.loc.Y + 10f && playerCharacter.loc.Y > character.loc.Y - 10f && ((playerCharacter.loc.X < character.loc.X + num / 2f && playerCharacter.loc.X > character.loc.X - num && playerCharacter.face == 1) || (playerCharacter.loc.X > character.loc.X - num / 2f && playerCharacter.loc.X < character.loc.X + num && playerCharacter.face == 0)))
					{
						return i;
					}
				}
			}
		}
		return -1;
	}

	internal int GetSanctuaryCreed(Player p)
	{
		int result = 0;
		Character playerCharacter = CharMgr.GetPlayerCharacter(p);
		if (playerCharacter != null)
		{
			int sanctuaryIn = MapMgr.sanctuaryMgr.GetSanctuaryIn(playerCharacter);
			if (sanctuaryIn > -1)
			{
				result = MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].creed;
			}
		}
		return result;
	}

	internal void DrawFore(float alpha)
	{
		float num = 1200f;
		float num2 = 600f;
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			if (sanctuaries[i] != null && sanctuaries[i].loc.X > ScrollManager.scroll.X - num && sanctuaries[i].loc.X < ScrollManager.scroll.X + num && sanctuaries[i].loc.Y > ScrollManager.scroll.Y - num2 && sanctuaries[i].loc.Y < ScrollManager.scroll.Y + num2)
			{
				sanctuaries[i].DrawFore(alpha);
			}
		}
	}

	internal void DrawBack(float alpha)
	{
		float num = 1200f;
		float num2 = 600f;
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			if (sanctuaries[i] != null && sanctuaries[i].loc.X > ScrollManager.scroll.X - num && sanctuaries[i].loc.X < ScrollManager.scroll.X + num && sanctuaries[i].loc.Y > ScrollManager.scroll.Y - num2 && sanctuaries[i].loc.Y < ScrollManager.scroll.Y + num2)
			{
				sanctuaries[i].DrawBack(alpha);
			}
		}
	}

	internal void DrawMapBack(float alpha)
	{
		float num = 1200f;
		float num2 = 600f;
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			if (sanctuaries[i] != null && sanctuaries[i].loc.X > ScrollManager.scroll.X - num && sanctuaries[i].loc.X < ScrollManager.scroll.X + num && sanctuaries[i].loc.Y > ScrollManager.scroll.Y - num2 && sanctuaries[i].loc.Y < ScrollManager.scroll.Y + num2)
			{
				sanctuaries[i].DrawMapBack(alpha);
			}
		}
	}

	internal int TransferSanctuaryCharToReserve(Character c)
	{
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			if (sanctuaries[i] == null)
			{
				continue;
			}
			for (int j = 0; j < sanctuaries[i].sanctuaryChar.Length; j++)
			{
				if (sanctuaries[i].sanctuaryChar[j].charIdx == c.ID)
				{
					sanctuaries[i].sanctuaryChar[j].charIdx = 9999;
					return j;
				}
			}
		}
		return -1;
	}

	internal void TransferReserveCharToSanctuary(int sanctuaryIdx, int sanctuaryCharIdx, Character c)
	{
		sanctuaries[sanctuaryIdx].sanctuaryChar[sanctuaryCharIdx].charIdx = c.ID;
	}

	internal void InitFromPlayer(Player p)
	{
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			if (sanctuaries[i] != null)
			{
				sanctuaries[i].InitFromPlayerCreed(p, i);
			}
		}
	}

	internal void InitToPlayer(Player p)
	{
		for (int i = 0; i < sanctuaries.Length; i++)
		{
			if (sanctuaries[i] != null)
			{
				p.sanctuaryCreed[i] = sanctuaries[i].creed;
				p.sanctuaryVisitCount[i] = sanctuaries[i].visitcount;
				for (int j = 0; j < sanctuaries[i].merchant.Length; j++)
				{
					p.sanctuaryPilgrim[i, j] = sanctuaries[i].merchant[j];
				}
			}
			else
			{
				p.sanctuaryCreed[i] = 0;
			}
		}
	}
}
using Microsoft.Xna.Framework;
using ProjectTower.character;
using ProjectTower.gamestate;
using ProjectTower.player;

namespace ProjectTower.sanctuary;

public class SanctuaryUpdate
{
	private Sanctuary sanctuary;

	public SanctuaryUpdate(Sanctuary sanctuary)
	{
		this.sanctuary = sanctuary;
	}

	internal int AddMerchant(int merchantType)
	{
		for (int i = 0; i < 4; i++)
		{
			if (sanctuary.merchant[i] == merchantType)
			{
				return -1;
			}
		}
		int randomInt = Rand.GetRandomInt(0, 2);
		for (int j = 0; j < 4; j++)
		{
			int num = 1;
			switch (randomInt)
			{
			case 0:
				switch (j)
				{
				case 0:
					num = 1;
					break;
				case 1:
					num = 2;
					break;
				case 2:
					num = 0;
					break;
				case 3:
					num = 3;
					break;
				}
				break;
			case 1:
				switch (j)
				{
				case 0:
					num = 2;
					break;
				case 1:
					num = 1;
					break;
				case 2:
					num = 3;
					break;
				case 3:
					num = 0;
					break;
				}
				break;
			}
			if (sanctuary.merchant[num] <= 0)
			{
				sanctuary.merchant[num] = merchantType;
				return num;
			}
		}
		return -2;
	}

	internal void AddGuardian()
	{
		bool flag = Rand.CoinToss(0.5f);
		for (int i = 0; i < 2; i++)
		{
			string text = "guardian";
			text = sanctuary.desecrationWave switch
			{
				1 => ((!flag || i != 0) && (flag || i != 1)) ? "guardian" : "guardmage", 
				2 => ((!flag || i != 0) && (flag || i != 1)) ? "guardian" : "guardmage", 
				3 => ((!flag || i != 0) && (flag || i != 1)) ? "guardmage" : "horseman", 
				_ => ((!flag || i != 0) && (flag || i != 1)) ? "guardian" : "guardmage", 
			};
			if (!(text != ""))
			{
				continue;
			}
			if (text == "guardian")
			{
				text = sanctuary.creed switch
				{
					2 => "guardian_cleric", 
					3 => "guardian", 
					5 => "guardian_rotten", 
					_ => "guardian_gen", 
				};
			}
			else if (text == "guardmage" && sanctuary.creed == 2)
			{
				text = "guardmage_cleric";
			}
			int face = i;
			Vector2 loc = new Vector2((float)sanctuary.left * 64f, (float)sanctuary.bottom * 64f * 0.5f - 64f);
			if (i == 0)
			{
				loc.X = (float)sanctuary.right * 64f + 64f;
				face = 0;
			}
			int num = -1;
			num = CharMgr.AddCharacter(text, loc, face, -1, 0);
			if (num <= -1)
			{
				continue;
			}
			Character character = CharMgr.character[num];
			character.sanctuaryIdx = sanctuary.ID;
			character.loc.Y = CharCols.GetGround(character.loc);
			character.state = 0;
			character.anim.SetAnimation("idle");
			int num2 = GameStateManager.GetMainCharacter().ID;
			if (GameStateManager.coopPlayerIdx > -1)
			{
				int charIdx = PlayerMgr.GetCoopPlayer().charIdx;
				if ((CharMgr.character[charIdx].loc - sanctuary.loc).LengthSquared() < (CharMgr.character[num2].loc - sanctuary.loc).LengthSquared())
				{
					num2 = charIdx;
				}
			}
			character.charAI.targetIdx = num2;
			character.charAI.alertMode = 2;
			character.charAI.alertFrame = 20f;
			character.charAI.job = 3;
			character.charAI.jobFrame = 10f;
			character.aggrod = true;
			character.charAI.attackFrame = -1f;
		}
	}
}

