	internal void SetCreedLoadout(Player p)
	{
		if (shrine)
		{
			for (int i = 0; i < 10; i++)
			{
				if (p.creedLevel[i] >= 1)
				{
					creed = i;
				}
			}
		}
		int j = 0;
		p.pickup = null;
		Character playerCharacter = CharMgr.GetPlayerCharacter(p);
		if (playerCharacter != null)
		{
			for (int k = 0; k < p.playerInv.inventory.Length; k++)
			{
				if (p.playerInv.inventory[k] != null && IsCreedLoadoutItem(p.playerInv.inventory[k]))
				{
					while (p.playerInv.inventory[k] != null)
					{
						p.playerInv.RemoveConsumable(k, playerCharacter, removeSanctuaryItems: true);
					}
					if (creed > 0)
					{
						AddCreedItem(p, j, playerCharacter);
					}
					j++;
				}
				GetCreedLoadoutSlot(p);
			}
			if (!shrine)
			{
				if (SteamServiceMgr.sanctuaryBuffer == null)
				{
					SteamServiceMgr.sanctuaryBuffer = new int[12];
				}
				SteamServiceMgr.sanctuaryBuffer[0] = ID;
				SteamServiceMgr.sanctuaryBuffer[1] = creed;
				SteamServiceMgr.sanctuaryBuffer[2] = p.stats.level;
				SteamServiceMgr.sanctuaryBuffer[3] = p.creedLevel[creed];
				SteamDataConversion.StringToIntArray(playerCharacter.equipment.SerializeToString(), SteamServiceMgr.sanctuaryBuffer, 4, 8);
				SteamServiceMgr.GetLeaderboard("SANCTUARY", 13);
			}
		}
		for (; j < 4; j++)
		{
			if (creed > 0)
			{
				AddCreedItem(p, j, playerCharacter);
			}
		}
	}

