	private void UpdatePlayerChar(Player p, Vector2 pLoc)
	{
		if (c.state == 0)
		{
			canAirGlide = 2;
			canDoubleJump = true;
			if (!(c.anim.animName == "hitlanddie"))
			{
				lastGroundedLoc = c.loc;
				grabLastGroundedLoc = c.loc;
				int col = CharCols.GetCol(c.loc + new Vector2(0f, 4f));
				if ((uint)(col - 90) > 9u && (uint)(col - 1101) > 1u && (col < 100 || col >= 1100))
				{
					lastSafeGroundedLoc = c.loc;
				}
			}
		}
		else
		{
			switch (c.anim.animName)
			{
			case "ladder":
			case "ladderup":
			case "ladderdown":
			case "slided":
				lastGroundedLoc = c.loc;
				grabLastGroundedLoc = c.loc;
				canAirGlide = 2;
				canDoubleJump = true;
				break;
			}
		}
		if (pSanct > -1)
		{
			if (MapMgr.sanctuaryMgr.sanctuaries[pSanct].desecrationFrame > 6f)
			{
				if (MapMgr.sanctuaryMgr.GetSanctuaryIn(c) == -1)
				{
					c.loc.X = pLoc.X;
				}
			}
			else
			{
				if (MapMgr.sanctuaryMgr.sanctuaries[pSanct].desecrationFrame > 0f || p.ID == GameStateManager.coopPlayerIdx)
				{
					return;
				}
				int sanctuaryIn = MapMgr.sanctuaryMgr.GetSanctuaryIn(c);
				if (sanctuaryIn <= -1)
				{
					return;
				}
				Sanctuary sanctuary = MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn];
				if (!sanctuary.shrine)
				{
					if (p.creedStanding[sanctuary.creed] < 0)
					{
						sanctuary.desecrationFrame = 1f;
						sanctuary.desecrationWave = 1;
						sanctuary.desecrationWavesTotal = 3;
						p.creedStanding[sanctuary.creed] = -1;
					}
					else if (p.corruption >= 100 && p.creedLevel[sanctuary.creed] <= 0 && sanctuary.creed != 0)
					{
						sanctuary.desecrationFrame = 1f;
						sanctuary.desecrationWave = 1;
						sanctuary.desecrationWavesTotal = 3;
						p.creedStanding[sanctuary.creed] = -1;
					}
				}
			}
		}
		else if (MapMgr.sanctuaryMgr.GetSanctuaryIn(c) > -1 && pSanct == -1 && p.ID != GameStateManager.coopPlayerIdx)
		{
			p.sanctuaryRespawnLoc = pLoc;
			p.sanctuaryRespawnLoc.Y = CharCols.GetGround(p.sanctuaryRespawnLoc);
		}
	}

	private bool UpdateHostileSanctuaryNPC()
	{
		Sanctuary sanctuary = MapMgr.sanctuaryMgr.sanctuaries[c.sanctuaryIdx];
		if (sanctuary.desecrationFrame > 0f && (c.loc.X < (float)sanctuary.left * 64f - 64f || c.loc.X > (float)sanctuary.right * 64f + 64f))
		{
			bool flag = false;
			for (int i = 0; i < sanctuary.sanctuaryChar.Length; i++)
			{
				if (sanctuary.sanctuaryChar[i].charIdx == c.ID)
				{
					sanctuary.sanctuaryChar[i].charIdx = -1;
					flag = true;
				}
			}
			if (flag)
			{
				c.exists = false;
			}
			else
			{
				if (c.loc.X < (float)sanctuary.left * 64f - 64f)
				{
					c.loc.X = (float)sanctuary.left * 64f - 64f;
				}
				if (c.loc.X > (float)sanctuary.right * 64f + 64f)
				{
					c.loc.X = (float)sanctuary.right * 64f + 64f;
				}
				if (c.loc.Y < (float)sanctuary.top * 32f)
				{
					c.loc.Y = (float)sanctuary.top * 32f;
				}
			}
			return true;
		}
		return false;
	}

